select 'usuario' t, count(*) n from public.usuario union all select 'propietario' t, count(*) n from public.propietario union all select 'animal' t, count(*) n from public.animal union all select 'proveedor' t, count(*) n from public.proveedor union all select 'medicamento' t, count(*) n from public.medicamento union all select 'lote' t, count(*) n from public.lote union all select 'tratamiento' t, count(*) n from public.tratamiento union all select 'dosis' t, count(*) n from public.dosis union all select 'movimiento_inventario' t, count(*) n from public.movimiento_inventario union all select 'mensaje_bot' t, count(*) n from public.mensaje_bot union all select 'alerta' t, count(*) n from public.alerta union all select 'auditoria' t, count(*) n from public.auditoria union all select 'auditoria_detalle' t, count(*) n from public.auditoria_detalle union all select 'intercambio' t, count(*) n from public.intercambio union all select 'documento_veterinario' t, count(*) n from public.documento_veterinario union all select 'importacion' t, count(*) n from public.importacion union all select 'importacion_registro' t, count(*) n from public.importacion_registro order by 1;
